// Limpieza y normalización de correos (unidad CODE)
// Saca el HTML, corta el historial del hilo y las firmas, y recorta el texto.
const MAX_CHARS = 1200;

function htmlATexto(html) {
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

function normalizeContent(texto) {
  let limpio = String(texto || '').replace(/\r/g, '');
  const cortes = [
    /^\s*El .{0,200}escribi[oó]:\s*$/im,
    /^\s*On .{0,200}wrote:\s*$/im,
    /^-{2,}\s*(Original Message|Mensaje original)\s*-{2,}/im,
    /^\s*De:\s.*$/im,
    /^\s*From:\s.*$/im,
    /^--\s*$/m,
    /^Enviado desde mi /im,
    /^Sent from my /im
  ];
  for (const patron of cortes) {
    const m = limpio.match(patron);
    if (m && m.index > 0) limpio = limpio.slice(0, m.index);
  }
  limpio = limpio
    .split('\n')
    .filter((linea) => !linea.trim().startsWith('>'))
    .join('\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  return limpio.length > MAX_CHARS ? limpio.slice(0, MAX_CHARS) + '…' : limpio;
}

const correos = $input.all()
  .filter((item) => item.json && item.json.id)
  .map((item) => {
    const c = item.json;
    const cuerpo = c.text ? c.text : htmlATexto(c.html);
    return {
      id: c.id,
      threadId: c.threadId,
      de: (c.from && c.from.text) || '',
      asunto: c.subject || '(sin asunto)',
      fecha: c.date || '',
      cuerpo: normalizeContent(cuerpo)
    };
  });

return [{ json: { total: correos.length, correos } }];

// Clasifica el error de Gmail y calcula el backoff exponencial con jitter.
// Solo se reintentan errores TRANSITORIOS (429, 5xx, timeouts y cortes de red).
// Los 4xx (400, 401, 403, 404) son permanentes: reintentarlos solo gasta recursos.
const MAX_INTENTOS = 3;
const req = $('Preparar intento').last().json;
const entrada = $input.first().json || {};
const err = entrada.error || entrada;
const mensaje = (typeof err === 'string' ? err : String(err.message || err.description || JSON.stringify(err))).slice(0, 300);

let status = Number(err.httpCode || err.status || err.statusCode || 0);
if (!status) {
  const m = mensaje.match(/\b([45]\d\d)\b/);
  if (m) status = Number(m[1]);
}
if (!status) {
  // n8n a veces informa el error solo con texto: lo traducimos al código HTTP
  const porTexto = [
    [/bad request|invalid/i, 400],
    [/unauthori[sz]ed|invalid credentials|token/i, 401],
    [/forbidden|insufficient permission/i, 403],
    [/not found/i, 404],
    [/too many requests|rate limit|quota/i, 429],
    [/internal server error/i, 500],
    [/bad gateway/i, 502],
    [/service unavailable|unavailable/i, 503],
    [/gateway timeout/i, 504]
  ];
  for (const [patron, codigo] of porTexto) {
    if (patron.test(mensaje)) { status = codigo; break; }
  }
}

const porRed = /timeout|timed out|ETIMEDOUT|ECONNRESET|ECONNREFUSED|ENOTFOUND|socket hang up|network/i.test(mensaje);
const transitorio = [429, 500, 502, 503, 504].includes(status) || porRed;
const intento = Number(req.intento || 0);
const reintentar = transitorio && intento + 1 < MAX_INTENTOS;

// Backoff exponencial: 1 s, 2 s, 4 s… más jitter aleatorio de 0,1 a 0,5 s
const espera = Math.pow(2, intento) + Math.round((0.1 + Math.random() * 0.4) * 100) / 100;

return [{
  json: {
    consulta: req.consulta,
    cantidad: req.cantidad,
    intento,
    reintentar,
    espera_seg: espera,
    http_status: status || null,
    tipo_error: transitorio ? 'transitorio' : 'permanente',
    mensaje
  }
}];
